def gen(rng):
    def fmt(xs, ys):
        return str(len(xs)) + '\n' + '\n'.join(f'{a} {b}' for a, b in zip(xs, ys))

    def distinct(n, hi):
        return rng.sample(range(1, hi + 1), n)

    tests = [fmt([5], [9]), fmt([1, 2], [1, 2]), fmt([1, 2], [2, 1]), fmt([2, 1], [1, 2]),
             fmt([1, 2, 3], [1, 2, 3]), fmt([1, 2, 3], [3, 2, 1]), fmt([3, 1, 2], [2, 3, 1])]
    for n in (3, 4, 5, 7, 9, 12, 15, 20):
        for hi in (n, 30, 1000):
            if hi >= n:
                tests.append(fmt(distinct(n, hi), distinct(n, hi)))
    for n in (6, 10, 16):
        xs = list(range(1, n + 1))
        ys = distinct(n, 1000)
        tests.append(fmt(xs, sorted(ys)))
        tests.append(fmt(xs, sorted(ys, reverse=True)))
        tests.append(fmt(xs, [1001 - v for v in sorted(ys)]))
    N = 10**5
    H = 10**6
    xs = sorted(distinct(N, H))
    ys = sorted(distinct(N, H))
    tests.append(fmt(xs, ys))                      # right chain, depth n
    tests.append(fmt(xs, ys[::-1]))                # left chain, depth n
    tests.append(fmt(distinct(N, H), distinct(N, H)))   # random shape
    perm = list(range(N))
    rng.shuffle(perm)
    tests.append(fmt([xs[i] for i in perm], [ys[i] for i in perm]))
    return tests
